// Pull the evidence out of each forwarded scam: who sent it, links, wallet addresses, handles.
// Nothing here is clicked or visited; it is only recorded.
const events = [];
for (const item of $input.all()) {
  const m = item.json;
  if (!m || !m.id) continue;
  const text = [m.subject || '', m.text || '', m.textAsHtml || '', m.html || ''].join('\n');
  const uniq = a => [...new Set(a)].slice(0, 25);
  const links = uniq((text.match(/https?:\/\/[^\s"'<>)\]]+/gi) || []).map(u => u.replace(/[.,;]+$/, '')).filter(u => !/google\.com|gstatic|googleusercontent/i.test(u)));
  const evm = uniq((text.match(/\b0x[a-fA-F0-9]{40}\b/g) || []).map(a => a.toLowerCase()));
  const btc = uniq(text.match(/\b(bc1[a-z0-9]{25,62}|[13][a-km-zA-HJ-NP-Z1-9]{25,34})\b/g) || []);
  const handles = uniq((text.match(/(?:t\.me\/|telegram\.me\/)[A-Za-z0-9_]{4,}|(?<![\w.])@[A-Za-z0-9_]{4,30}\b/g) || []).filter(h => !/@(gmail|12redflags|cnsplanet|googlemail)/i.test(h)));
  const fromHdr = (m.from && (m.from.text || (m.from.value || []).map(v => v.address).join(', '))) || '';
  events.push({
    token: 'scam-inbox', type: 'scam_report', wallet: fromHdr.slice(0, 200), tx_hash: m.id,
    detail: { subject: (m.subject || '').slice(0, 300), date: m.date, from: fromHdr.slice(0, 200), links, evm_addresses: evm, btc_addresses: btc, handles,
      snippet: (m.text || '').replace(/\s+/g, ' ').slice(0, 500) }
  });
}
if (!events.length) return [];
return [{ json: { events } }];
